"""File handling for generated DMX YAML."""

from __future__ import annotations

from collections.abc import Mapping
import difflib
from pathlib import Path
import re
from typing import Any

from homeassistant.util.file import write_utf8_file_atomic
import yaml

from .model_dmx import DMX_DOMAIN, to_yaml_dict

HEADER = (
    "# Generated by DMX Config UI (dmx_config_ui).\n"
    "# Do not edit manually – changes are overwritten on the next deploy.\n"
)
CONFIGURATION_FILE = "configuration.yaml"


class _Dumper(yaml.SafeDumper):
    """SafeDumper that indents block sequences inside mappings."""

    def increase_indent(self, flow: bool = False, indentless: bool = False) -> Any:
        return super().increase_indent(flow, False)


def _dump(data: Any) -> str:
    return yaml.dump(
        data,
        Dumper=_Dumper,
        sort_keys=False,
        allow_unicode=True,
        default_flow_style=False,
        width=1000,
    )


def render_dmx_yaml(config: Mapping[str, Any]) -> str:
    """Render the dmx UI config as the content of the `dmx: !include` file."""
    return HEADER + _dump(to_yaml_dict(config))


def read_text(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None


def write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    write_utf8_file_atomic(str(path), content)


def unified_diff(old: str | None, new: str, name: str) -> str:
    return "".join(
        difflib.unified_diff(
            (old or "").splitlines(keepends=True),
            new.splitlines(keepends=True),
            fromfile=f"{name} (current)",
            tofile=f"{name} (new)",
        )
    )


def _include_pattern(include_file: str) -> re.Pattern[str]:
    return re.compile(
        rf"""^[^#\n]*!include\s+["']?{re.escape(include_file)}["']?\s*(#.*)?$""",
        re.MULTILINE,
    )


def is_included(configuration: str | None, include_file: str) -> bool:
    """Return True if configuration.yaml references the include file."""
    if not configuration:
        return False
    return bool(_include_pattern(include_file).search(configuration))


def add_include(configuration: str | None, include_file: str, key: str) -> str:
    """Append a top-level include."""
    line = f"{key}: !include {include_file}\n"
    if not configuration:
        return line
    if is_included(configuration, include_file):
        return configuration
    return configuration.rstrip("\n") + "\n\n" + line


def find_top_level_block(configuration: str | None, key: str) -> tuple[int, int] | None:
    """Return the (start, end) line indexes of a top-level `key:` block, if present."""
    if not configuration:
        return None
    lines = configuration.splitlines(keepends=True)
    pattern = re.compile(rf"^{re.escape(key)}\s*:(\s|$)")
    for start, line in enumerate(lines):
        if not pattern.match(line):
            continue
        end = start + 1
        last_content = start
        while end < len(lines):
            text = lines[end]
            stripped = text.strip()
            if stripped and not text[0].isspace() and not stripped.startswith("#"):
                break
            if stripped and not stripped.startswith("#"):
                last_content = end
            end += 1
        return start, last_content + 1
    return None


def add_dmx_include(configuration: str | None, include_file: str) -> tuple[str, bool]:
    """Point the top-level `dmx:` key to the include file.

    Returns the new content and whether an existing `dmx:` block was replaced.
    """
    if is_included(configuration, include_file):
        return configuration or "", False
    block = find_top_level_block(configuration, DMX_DOMAIN)
    if configuration is None or block is None:
        return add_include(configuration, include_file, DMX_DOMAIN), False
    lines = configuration.splitlines(keepends=True)
    start, end = block
    lines[start:end] = [f"{DMX_DOMAIN}: !include {include_file}\n"]
    return "".join(lines), True
